using System;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
internal sealed partial class ModernWorkspace {
 bool inboxProcessed,showArchivedHabits;string inboxQuery="";DateTime habitWeek=PersonalWorkflows.Monday(DateTime.Today),reviewWeek=PersonalWorkflows.Monday(DateTime.Today);
 void InboxPage(StackPanel root){
  var tools=new WrapPanel{Margin=new Thickness(0,0,0,15)};tools.Children.Add(Btn("+ Nouvelle idée",delegate{EditInbox(null);},true));tools.Children.Add(Btn(inboxProcessed?"À trier":"Déjà classées",delegate{inboxProcessed=!inboxProcessed;Refresh();},false,true));
  var search=new TextBox{Text=inboxQuery,Width=200,MaxLength=200};tools.Children.Add(search);tools.Children.Add(Btn("Rechercher",delegate{inboxQuery=search.Text;Refresh();},false,true));root.Children.Add(tools);root.Children.Add(T("Déposez vos idées sans choisir de projet. Classez-les ensuite en tâche, note ou nouveau projet.",12,Muted,new Thickness(0,0,0,18)));
  var items=store.Value.inbox.AsEnumerable().Reverse().Where(i=>i.processed==inboxProcessed&&(String.IsNullOrWhiteSpace(inboxQuery)||GlobalSearch.Normalize(i.title+" "+i.body).Contains(GlobalSearch.Normalize(inboxQuery)))).OrderByDescending(i=>i.created).ToList();
  if(items.Count==0)root.Children.Add(Card(inboxProcessed?"Aucune idée classée":"Votre boîte est à jour",T("La capture rapide propose maintenant une option À trier.",12,Muted)));
  foreach(var item in items){var idea=item;var body=new StackPanel();body.Children.Add(T(Finance.Day(idea.created).ToString("dd/MM/yyyy"),10,Muted));if(!String.IsNullOrEmpty(idea.body))body.Children.Add(T(idea.body.Length>240?idea.body.Substring(0,240)+"…":idea.body,12,Muted,new Thickness(0,10,0,12)));var actions=new WrapPanel();
   if(!idea.processed)actions.Children.Add(Btn("Classer cette idée",delegate{ClassifyInbox(idea);},true));else actions.Children.Add(Btn("Ouvrir le contenu classé",delegate{var target=GlobalSearch.Resolve(store.Value,new Favorite{kind=idea.resultKind,id=idea.resultId});if(target!=null)OpenSearchItem(target);else MessageBox.Show("Le contenu classé a été supprimé. Le texte de l'idée reste conservé ici.");},false,true));
   actions.Children.Add(Btn(idea.processed?"Relire":"Modifier",delegate{EditInbox(idea);},false,true));body.Children.Add(actions);var card=Card(idea.title,body);card.Margin=new Thickness(0,0,0,15);root.Children.Add(card);}
 }
 void EditInbox(InboxItem existing){
  StackPanel body,actions;var w=Dialog(existing==null?"Nouvelle idée":"Idée capturée",out body,out actions,590);var title=new TextBox{Text=existing==null?"":existing.title,MaxLength=200,IsReadOnly=existing!=null&&existing.processed};Field(body,"Titre",title);var text=new TextBox{Text=existing==null?"":existing.body,Height=200,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MaxLength=10000,IsReadOnly=existing!=null&&existing.processed};Field(body,"Détails",text);var error=T("",12,Accent);body.Children.Add(error);bool saved=false;
  if(existing!=null)actions.Children.Add(Btn("Supprimer",delegate{if(MessageBox.Show("Supprimer cette capture ? Le contenu déjà classé sera conservé.","Supprimer l'idée",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;try{PersonalWorkflows.Change(store,delegate{store.Value.inbox.RemoveAll(i=>i.id==existing.id);});saved=true;FinishFinanceDialog(w);}catch(Exception ex){error.Text=ex.Message;}},false,true));
  actions.Children.Add(Btn("Fermer",delegate{w.DialogResult=false;},false,true));if(existing==null||!existing.processed)actions.Children.Add(Btn("Enregistrer l'idée",delegate{if(saved)return;if(String.IsNullOrWhiteSpace(title.Text)){title.Focus();return;}try{PersonalWorkflows.Change(store,delegate{if(existing==null)store.Value.inbox.Add(new InboxItem{id=Guid.NewGuid().ToString(),title=title.Text.Trim(),body=text.Text,created=DateTime.Today.ToString("yyyy-MM-dd")});else{var item=store.Value.inbox.First(i=>i.id==existing.id);item.title=title.Text.Trim();item.body=text.Text;}});saved=true;FinishFinanceDialog(w);}catch(Exception ex){error.Text=ex.Message;}},true));ShowWindow(w);Refresh();
 }
 void ClassifyInbox(InboxItem item){
  StackPanel body,actions;var w=Dialog("Classer une idée",out body,out actions,530);var kind=Combo(new[]{"Tâche","Note","Nouveau projet"},"Tâche");Field(body,"Transformer en",kind);var name=new TextBox{Text=item.title,MaxLength=200};Field(body,"Titre ou nom du nouveau projet",name);var project=Combo(owner.AllProjects(),owner.AllProjects()[0]);Field(body,"Projet pour la tâche ou la note",project);kind.SelectionChanged+=delegate{project.IsEnabled=kind.SelectedIndex!=2;name.MaxLength=kind.SelectedIndex==2?80:200;};var error=T("",12,Accent);body.Children.Add(error);bool saved=false;
  actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Classer l'idée",delegate{if(saved)return;try{PersonalWorkflows.ConvertInbox(store,item.id,new[]{"task","note","project"}[kind.SelectedIndex],name.Text,Convert.ToString(project.SelectedItem));saved=true;FinishFinanceDialog(w);}catch(Exception ex){error.Text=ex.Message;}},true));ShowWindow(w);Refresh();
 }
 void HabitsPage(StackPanel root){
  var tools=new WrapPanel{Margin=new Thickness(0,0,0,16)};tools.Children.Add(Btn("+ Habitude",delegate{EditHabit(null);},true));tools.Children.Add(Btn("‹",delegate{habitWeek=habitWeek.AddDays(-7);Refresh();},false,true));tools.Children.Add(Btn("Cette semaine",delegate{habitWeek=PersonalWorkflows.Monday(DateTime.Today);Refresh();},false,true));tools.Children.Add(Btn("›",delegate{if(habitWeek.AddDays(7)<=DateTime.Today){habitWeek=habitWeek.AddDays(7);Refresh();}},false,true));tools.Children.Add(Btn(showArchivedHabits?"Habitudes actives":"Archives",delegate{showArchivedHabits=!showArchivedHabits;Refresh();},false,true));root.Children.Add(tools);
  root.Children.Add(T("Du "+habitWeek.ToString("dd/MM")+" au "+habitWeek.AddDays(6).ToString("dd/MM/yyyy")+" · cochez les jours réalisés.",12,Muted,new Thickness(0,0,0,18)));
  var habits=store.Value.habits.Where(h=>h.archived==showArchivedHabits).ToList();if(habits.Count==0)root.Children.Add(Card("Vos petites habitudes",T("Choisissez une activité et les jours où vous souhaitez la pratiquer.",13,Muted)));
  foreach(var habit in habits){var item=habit;var body=new StackPanel();body.Children.Add(T("Série actuelle : "+PersonalWorkflows.Streak(item,DateTime.Today)+" jour(s) prévu(s) réalisé(s)",11,Muted,new Thickness(0,0,0,12)));var grid=new UniformGrid{Columns=7};for(int i=0;i<7;i++){var date=habitWeek.AddDays(i);bool done=item.checks.Contains(date.ToString("yyyy-MM-dd"));var button=Btn(date.ToString("ddd dd",System.Globalization.CultureInfo.GetCultureInfo("fr-FR"))+(done?" ✓":""),delegate{try{PersonalWorkflows.ToggleHabit(store,item.id,date,DateTime.Today);Refresh();}catch(Exception ex){MessageBox.Show(ex.Message);}},done);button.IsEnabled=!item.archived&&date<=DateTime.Today&&PersonalWorkflows.Scheduled(item,date);button.Padding=new Thickness(5,12,5,12);button.Margin=new Thickness(0,0,5,0);grid.Children.Add(button);}body.Children.Add(grid);body.Children.Add(Btn("Modifier",delegate{EditHabit(item);},false,true));var card=Card(item.name,body);card.Margin=new Thickness(0,0,0,15);root.Children.Add(card);}
 }
 void EditHabit(Habit existing){
  StackPanel body,actions;var w=Dialog(existing==null?"Nouvelle habitude":"Modifier l'habitude",out body,out actions,540);var name=new TextBox{Text=existing==null?"":existing.name,MaxLength=120};Field(body,"Habitude",name);body.Children.Add(T("Jours souhaités",12,Muted));var row=new WrapPanel();var days=new List<CheckBox>();string[] labels={"Lun","Mar","Mer","Jeu","Ven","Sam","Dim"};for(int i=0;i<7;i++){var check=new CheckBox{Content=labels[i],IsChecked=existing==null||existing.days.Contains(i),Margin=new Thickness(0,10,16,10)};days.Add(check);row.Children.Add(check);}body.Children.Add(row);var archived=new CheckBox{Content="Archiver cette habitude",IsChecked=existing!=null&&existing.archived};body.Children.Add(archived);body.Children.Add(T("Le suivi commence à la création de l'habitude. Les jours futurs ne peuvent pas être cochés.",11,Muted,new Thickness(0,15,0,0)));var error=T("",12,Accent,new Thickness(0,15,0,0));body.Children.Add(error);bool saved=false;
  actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Enregistrer l'habitude",delegate{if(saved)return;var selected=Enumerable.Range(0,7).Where(i=>days[i].IsChecked==true).ToList();if(String.IsNullOrWhiteSpace(name.Text)||selected.Count==0){error.Text="Indiquez un nom et au moins un jour.";return;}try{PersonalWorkflows.Change(store,delegate{var item=existing==null?new Habit{id=Guid.NewGuid().ToString(),created=DateTime.Today.ToString("yyyy-MM-dd")}:store.Value.habits.First(h=>h.id==existing.id);item.name=name.Text.Trim();item.days=selected;item.archived=archived.IsChecked==true;if(existing==null)store.Value.habits.Add(item);});saved=true;FinishFinanceDialog(w);}catch(Exception ex){error.Text=ex.Message;}},true));ShowWindow(w);Refresh();
 }
 void WeekReviewPage(StackPanel root){
  var tools=new WrapPanel{Margin=new Thickness(0,0,0,18)};tools.Children.Add(Btn("‹",delegate{reviewWeek=reviewWeek.AddDays(-7);Refresh();},false,true));tools.Children.Add(Btn("Cette semaine",delegate{reviewWeek=PersonalWorkflows.Monday(DateTime.Today);Refresh();},false,true));tools.Children.Add(Btn("›",delegate{if(reviewWeek.AddDays(7)<=DateTime.Today){reviewWeek=reviewWeek.AddDays(7);Refresh();}},false,true));root.Children.Add(tools);root.Children.Add(T("Du "+reviewWeek.ToString("dd/MM")+" au "+reviewWeek.AddDays(6).ToString("dd/MM/yyyy"),20,Ink,new Thickness(0,0,0,18)));
  var week=PersonalWorkflows.Week(store.Value,reviewWeek);var summary=new UniformGrid{Columns=4};foreach(var item in new[]{new[]{"Tâches terminées",week.Tasks.ToString()},new[]{"Projets avancés",week.Projects.ToString()},new[]{"Concentration",Math.Round(week.FocusSeconds/60.0).ToString()+" min"},new[]{"Habitudes cochées",week.HabitChecks.ToString()}}){var body=new StackPanel();body.Children.Add(T(item[0],10,Muted));body.Children.Add(T(item[1],25,Ink,new Thickness(0,10,0,0)));var box=Box(body,new Thickness(15));box.Margin=new Thickness(0,0,10,0);summary.Children.Add(box);}root.Children.Add(summary);
  var tasks=new StackPanel();foreach(var task in week.Completed.Take(30))tasks.Children.Add(T(task.title+" · "+task.project,12,Muted,new Thickness(0,8,0,4)));if(week.Tasks==0)tasks.Children.Add(T("Aucune tâche terminée avec une date de fin dans cette semaine.",12,Muted));var taskCard=Card("Ce que vous avez terminé",tasks);taskCard.Margin=new Thickness(0,18,0,18);root.Children.Add(taskCard);
  var focus=new StackPanel();for(int i=0;i<7;i++){var day=reviewWeek.AddDays(i);long seconds=week.Sessions.Where(s=>new DateTime(s.endedUtcTicks,DateTimeKind.Utc).ToLocalTime().Date==day).Sum(s=>(long)s.seconds);focus.Children.Add(T(day.ToString("ddd dd",System.Globalization.CultureInfo.GetCultureInfo("fr-FR"))+" · "+Math.Round(seconds/60.0)+" min",12,Muted,new Thickness(0,7,0,7)));}root.Children.Add(Card("Temps de concentration par jour",focus));
  root.Children.Add(T("Les sessions terminées ou arrêtées sont comptabilisées, sans les pauses. Les anciennes tâches sans date de fin ne sont pas attribuées à une semaine.",11,Muted,new Thickness(0,18,0,0)));
 }
 StackPanel InboxHome(bool compact){var body=new StackPanel();var items=store.Value.inbox.AsEnumerable().Reverse().Where(i=>!i.processed).ToList();body.Children.Add(T(items.Count+" idée(s) à trier",16));foreach(var item in items.Take(compact?2:4)){var idea=item;body.Children.Add(Btn(idea.title,delegate{ClassifyInbox(idea);},false,true));}body.Children.Add(Btn("+ Capturer une idée",Capture,false,true));return body;}
 StackPanel HabitsHome(bool compact){var body=new StackPanel();foreach(var item in store.Value.habits.Where(h=>!h.archived&&PersonalWorkflows.Scheduled(h,DateTime.Today)).Take(compact?3:6)){var habit=item;var check=new CheckBox{Content=habit.name,IsChecked=habit.checks.Contains(DateTime.Today.ToString("yyyy-MM-dd"))};check.Click+=delegate{try{PersonalWorkflows.ToggleHabit(store,habit.id,DateTime.Today,DateTime.Today);Refresh();}catch(Exception ex){MessageBox.Show(ex.Message);}};body.Children.Add(check);}if(body.Children.Count==0)body.Children.Add(T("Aucune habitude prévue aujourd'hui.",12,Muted));return body;}
}
